(function(){
  'use strict';
  var C=globalThis.SpellCore,STORE='ciya-spelling-v1',main=document.getElementById('main'),dialog=document.getElementById('dialog');
  var data,db,state,session=null,settings={goal:20,rate:.85,accent:'en-US',autoAudio:true},route='home',filter={query:'',category:'all',status:'all'},page=1,loaded=false,loadError='',storageError='',rawStored='',toastTimer,offlineStatus='正在准备离线小本…',audio=null,hintView='',staged=null,startChoice=null;
  var categoryIcons={nouns:'n.',verbs:'v.',adjectives:'adj.',adverbs:'adv.',affixes:'-ly',family:'Aa',function:'&',shape:'a↔e',sound:'♪',short:'abc',long:'abc…'};
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function btn(label,action,cls,extra){return '<button type="button" class="btn '+(cls||'')+'" data-act="'+action+'" '+(extra||'')+'>'+label+'</button>';}
  function categoryName(id){return db.categories.get(id)?.title||({wrong:'累计错词',due:'到期复习',favorites:'收藏词'}[id])||'全部核心词';}
  function toast(text){var el=document.getElementById('toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(function(){el.hidden=true;},3600);}
  function clone(v){return JSON.parse(JSON.stringify(v));}
  function envelope(s,se,options){return {app:'ciya-spelling',version:1,savedAt:Date.now(),learning:C.exportBackup(s,se),settings:options};}
  function checkedSettings(raw){if(!raw||![10,20,30,50].includes(raw.goal)||![.65,.85,1].includes(raw.rate)||!['en-US','en-GB'].includes(raw.accent)||typeof raw.autoAudio!=='boolean')throw Error('偏好设置格式不正确。');return {goal:raw.goal,rate:raw.rate,accent:raw.accent,autoAudio:raw.autoAudio};}
  function validateEnvelope(raw){if(!raw||raw.app!=='ciya-spelling'||raw.version!==1||!Number.isFinite(raw.savedAt))throw Error('这不是词芽的完整备份。');var clean=C.validateBackup(raw.learning,db);return {state:clean.state,session:clean.session,settings:checkedSettings(raw.settings)};}
  function storageBanner(){var el=document.getElementById('save-status');if(!el)return;el.hidden=!storageError;el.innerHTML=storageError?esc(storageError)+' '+btn('导出当前记录','backup','secondary small'):'';}
  function persist(){if(loadError)return false;try{localStorage.setItem(STORE,JSON.stringify(envelope(state,session,settings)));storageError='';storageBanner();return true;}catch(_){storageError='本次修改尚未保存，浏览器可能没有足够空间。请导出当前记录后再关闭页面。';storageBanner();return false;}}
  function saveLoad(){try{rawStored=localStorage.getItem(STORE)||'';if(rawStored){var clean=validateEnvelope(JSON.parse(rawStored));state=clean.state;session=clean.session;settings=clean.settings;}else state=C.emptyState();}catch(err){loadError='学习记录暂时无法读取，原始内容已保留。请先导出原始记录，再恢复有效备份。';state=C.emptyState();}}
  function navigate(hash){if(location.hash==='#'+hash)readRoute();else location.hash=hash;}
  function readRoute(){if(!loaded)return;var parts=location.hash.slice(1).split('?'),name=parts[0]||'home',params=new URLSearchParams(parts[1]||'');route=['home','practice','summary','words','mistakes','mine'].includes(name)?name:'home';if(['words','mistakes'].includes(route)){filter={query:params.get('search')||'',category:db.categories.has(params.get('category'))?params.get('category'):'all',status:params.get('status')||(route==='mistakes'?'active':'all')};page=1;}closeDialog();render();window.scrollTo(0,0);}
  function cat(){return '<svg class="cat-art" viewBox="0 0 240 240" aria-hidden="true"><ellipse cx="129" cy="213" rx="86" ry="12" fill="#e7dab3" opacity=".5"/><path d="M46 169c-24-6-32-28-22-35 12-6 13 15 26 10" fill="#edcfaa" stroke="#c2a386" stroke-width="2.5"/><path d="M71 177c-15-39 0-76 45-79 47-1 68 36 57 80" fill="#f7e5c8" stroke="#bba18d" stroke-width="2.5"/><path d="m66 104 2-43 31 18c13-6 29-6 42-1l29-19 1 45c14 15 12 43-7 55-24 15-57 16-81 0-20-12-27-34-17-55Z" fill="#fff6e4" stroke="#bba18d" stroke-width="2.5" stroke-linejoin="round"/><path d="m75 83 1-10 12 9M152 82l12-9-1 13" fill="#eac0ad" stroke="#eac0ad" stroke-width="5" stroke-linecap="round"/><path d="m91 120 7 2m43 0 7-2" fill="none" stroke="#7a6c67" stroke-width="4" stroke-linecap="round"/><path d="m118 130 5 3 5-3m-5 3v5m0 0c-4 5-9 2-10 0m10 0c4 5 9 2 10 0" fill="none" stroke="#9e7d72" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="84" cy="134" rx="9" ry="5" fill="#edc4b8"/><ellipse cx="157" cy="134" rx="9" ry="5" fill="#edc4b8"/><path d="m55 174 64 12 65-13-6 36-59 7-59-9Z" fill="#baa7cf" stroke="#947fa5" stroke-width="2.5" stroke-linejoin="round"/><path d="m119 186 1 29m-52-33 36 8m32-1 34-8" fill="none" stroke="#e9def0" stroke-width="3" stroke-linecap="round"/><ellipse cx="65" cy="180" rx="14" ry="9" fill="#fff2dd" stroke="#bba18d" stroke-width="2.5" transform="rotate(17 65 180)"/><ellipse cx="177" cy="180" rx="14" ry="9" fill="#fff2dd" stroke="#bba18d" stroke-width="2.5" transform="rotate(-17 177 180)"/><path d="m198 69 1 10m-5-5h10M42 94v9m-4-5h9" stroke="#b6bb8c" stroke-width="2.5" stroke-linecap="round"/><path d="m194 117 7-2 3 6-6 4Z" fill="#d4c1de"/><path d="m46 49 4-7 5 6-4 5Z" fill="#dfc38a"/></svg>';}
  function daily(){return state.days[C.dayKey(Date.now())]||{attempts:0,cleanCorrect:0};}
  function footer(){return '<footer class="page-footer">一词一小步，慢慢长出自己的词汇量。<br><a href="#mine">词库来源与备份</a> · <a href="../words/">打开词辨</a> · <a href="../latest.html#overview">回到研习</a></footer>';}
  function home(){var sum=C.summary(state),d=daily(),resume=session&&session.completedAt===null,percent=Math.min(100,d.attempts/settings.goal*100);return '<div class="hero-layout"><section class="hero"><div class="hero-content"><p class="eyebrow">HELLO, LITTLE LEARNER</p><h1>把单词，<br>一个个记住。</h1><p class="intro">看见中文，写出英文。<br>小猫陪你，一起把拼写练清楚。</p><div class="hero-buttons">'+btn(resume?'继续上次默写':'开始一组 '+settings.goal+' 词',resume?'resume':'quick-start','primary')+btn('选分类 / 词数','setup','secondary')+'</div></div>'+cat()+'</section><aside class="daily-card"><h2>今日默写</h2><div class="daily-number">'+d.attempts+'<small>/ '+settings.goal+' 次</small></div><p>'+(d.attempts>=settings.goal?'今日小目标完成啦，按自己的节奏继续。':'先写几个，把学习的节奏找回来。')+'</p><div class="daily-track" aria-label="今日目标完成'+Math.round(percent)+'%"><span style="width:'+percent+'%"></span></div><p class="tiny-text">其中 '+d.cleanCorrect+' 次独立写对</p></aside></div><section class="stats" aria-label="学习进度"><button class="stat" data-act="library-filter" data-status="attempted"><div><strong>'+sum.attempted+'<small style="font-size:11px;color:#b3a4b9"> / '+db.total+'</small></strong><span>练习过的词</span></div><span class="stat-symbol" aria-hidden="true">✎</span></button><button class="stat" data-act="library-filter" data-status="mastered"><div><strong>'+sum.mastered+'</strong><span>连续3次独立写对</span></div><span class="stat-symbol" aria-hidden="true">❀</span></button><button class="stat" data-act="library-filter" data-status="due"><div><strong>'+sum.due+'</strong><span>到期复习的词</span></div><span class="stat-symbol" aria-hidden="true">↻</span></button></section><div class="section-heading"><h2>分组练一练</h2><a class="quiet-link" href="#words">看看全部 '+db.total+' 词 →</a></div><section class="category-grid">'+['nouns','verbs','adjectives','adverbs','affixes','family'].map(function(id){var c=db.categories.get(id);return '<button class="category-card" data-act="category" data-category="'+id+'"><span class="category-icon" aria-hidden="true">'+categoryIcons[id]+'</span><span class="arrow" aria-hidden="true">↗</span><h3>'+esc(c.title)+'</h3><p>'+c.count+' 词 · '+({nouns:'事物、过程与概念',verbs:'动作、状态与变化',adjectives:'性质、程度与评价',adverbs:'频率、方式与语气',affixes:'记清词中与词尾差别',family:'同一个词根，不同词性'}[id])+'</p></button>';}).join('')+'</section><section class="soft-banner"><div><h3>长得像、听着像，单独练一下</h3><p>写错后看清区别，别再让相近的词偷偷换位。</p></div><div>'+btn('字形相近','category','secondary small','data-category="shape"')+' '+btn('读音相近','category','secondary small','data-category="sound"')+'</div></section>'+footer();}
  function practice(){if(!session||!session.ids.length)return empty('还没有开始默写','选择一小组单词，就能开始。',btn('开始一组','setup',''));if(session.completedAt!==null)return roundSummary();var word=db.words.get(session.ids[session.index]),r=session.results[word.id],favorite=state.records[word.id]?.favorite,audioMode=session.mode==='audio',showMeaning=!audioMode||r||hintView==='meaning';return '<div class="practice-wrap"><div class="practice-top"><a href="#home">‹ 回到小本，进度会保留</a><span>第 '+(session.index+1)+' / '+session.ids.length+' 词</span></div><div class="progress-line"><span style="width:'+(session.index/session.ids.length*100)+'%"></span></div><article class="practice-card"><div class="practice-kicker"><span class="pill">'+(audioMode?'听音默写':'看中文默写')+' · '+esc(categoryName(session.category))+'</span><button class="star-btn '+(favorite?'saved':'')+'" data-act="favorite" data-id="'+esc(word.id)+'" aria-label="'+(favorite?'取消收藏':'收藏当前单词')+'">'+(favorite?'★':'☆')+'</button></div><div class="prompt-area">'+(audioMode&&!r?'<button class="audio-prompt" data-act="listen" aria-label="播放当前单词读音">♪</button><p class="audio-caption">听清单词，再把它写下来</p>':'')+(showMeaning?'<p class="prompt-pos">'+esc(word.pos)+'</p><h2 class="meaning">'+esc(word.meaning)+'</h2>':'')+'<p class="word-length">'+word.word.replace(/[^a-z]/g,'').length+' 个字母'+(/[-' ]/.test(word.word)?' · 保留连字符与空格':'')+'</p>'+(hintView==='first'?'<p class="revealed-hint">首字母：<strong>'+esc(word.word[0])+'</strong></p>':'')+(hintView==='phonetic'?'<p class="revealed-hint">音标：'+phonetic(word)+'</p>':'')+'</div><form id="answer-form"><label class="spelling-label" for="spelling-input">把你记得的英文写在这里</label><input type="text" id="spelling-input" class="answer-input'+(r?(r.correct?' right':' wrong'):'')+'" value="'+esc(session.draft)+'" maxlength="120" lang="en" inputmode="text" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" '+(r?'disabled':'')+' placeholder="Type the word…" aria-describedby="hint-note"><div class="answer-actions">'+(r?btn(session.index===session.ids.length-1?'看看这一轮的收获':'下一词 →','next','primary-action'):'<button type="submit" class="btn primary-action">检查拼写</button>'+btn('暂时想不起','skip','ghost'))+'</div></form>'+(!r?'<div class="hint-actions">'+(audioMode?btn('看中文提示','hint-meaning','ghost small'):btn('看首字母','hint-first','ghost small')+btn('看音标','hint-phonetic','ghost small')+btn('听一听','listen','ghost small'))+'</div><p class="keyboard-note" id="hint-note">Enter 检查 · 使用提示后，会保留提示记录</p>':feedback(word,r))+'</article><div class="round-note"><span>本轮 '+Object.values(session.results).filter(function(v){return v.independentCorrect;}).length+' 词独立写对</span><span>'+(session.hintUsed?'这题用过提示，会安排再复习。':'进度自动保存在这台设备')+'</span></div></div>';}
  function phonetic(w){return '/'+esc(w.phonetic.replace(/^\/|\/$/g,''))+'/';}
  function feedback(word,r){var title=r.independentCorrect?'写对啦，独立想起来了。':r.correct?'写对了，这词再复习一次。':r.skipped?'先把这一词记清楚。':'这次有差别，直接看清楚。',known=db.words.get(C.normalize(r.typed)),diff=!r.correct&&!r.skipped?C.letterDiff(word.word,r.typed):[],family=(word.comparisonGroups||[]).map(function(id){return data.groups.find(function(g){return g.id===id;});}).find(Boolean),nearby=C.nearby(db,word,6),variant=r.correct&&C.normalize(r.typed)!==C.normalize(word.word);return '<section class="feedback" aria-live="polite"><p class="feedback-title '+(!r.independentCorrect?'needs-review':'')+'">'+title+'</p><div class="target-word"><strong>'+esc(word.word)+'</strong><button class="audio-btn" data-act="listen" aria-label="朗读正确单词">♪</button></div><p class="meaning-note">'+phonetic(word)+(variant?' · 你写的 '+esc(C.normalize(r.typed))+' 也是已收录的规范拼写。':'')+'</p>'+(diff.length?'<p class="letter-diff-label">正确拼写 · 有颜色的位置需要注意</p><div class="letter-diff" aria-label="正确拼写与输入的字母差异">'+diff.map(function(x){return '<span class="'+(x.type==='equal'?'same':x.type==='delete'?'missing':'changed')+'" title="'+esc(x.type==='insert'?'多写了 '+x.typed:x.type==='delete'?'少写了 '+x.expected:x.type==='replace'?'把 '+x.expected+' 写成了 '+x.typed:'这个字母正确')+'">'+esc(x.expected||(x.typed?'('+x.typed+')':'·'))+'</span>';}).join('')+'</div>':'')+(known&&known.id!==word.id&&!r.correct?'<div class="confusion-note"><strong>你写的是另一个词：'+esc(known.word)+'</strong><p>'+esc(known.meaning)+'</p><p>本题的目标是 <strong>'+esc(word.word)+'</strong>：'+esc(word.meaning)+'</p></div>':'')+(word.example?'<div class="example-note"><p>'+highlightWord(word.example.sentence,word.word)+'</p><p style="color:#a18ca9;margin-top:5px">'+esc(word.example.zh)+'</p></div>':'')+(family?'<div class="confusion-note"><strong>'+esc(family.title)+'</strong><p>'+esc(family.contrast)+'</p></div>':'')+(nearby.length?'<div class="similar-row"><small class="muted">再对照：</small>'+nearby.map(function(w){return btn(esc(w.word),'word-detail','secondary small','data-id="'+esc(w.id)+'"');}).join('')+'</div>':'')+'</section>';}
  function highlightWord(sentence,word){var lower=sentence.toLowerCase(),i=lower.indexOf(word.toLowerCase());return i<0?esc(sentence):esc(sentence.slice(0,i))+'<strong>'+esc(sentence.slice(i,i+word.length))+'</strong>'+esc(sentence.slice(i+word.length));}
  function roundSummary(){if(!session)return home();var results=session.ids.map(function(id){return session.results[id];}).filter(Boolean),clean=results.filter(function(r){return r.independentCorrect;}).length,hinted=results.filter(function(r){return r.correct&&!r.independentCorrect;}).length,missed=results.length-clean-hinted,needs=results.filter(function(r){return !r.independentCorrect;});return '<section class="summary-card"><span class="summary-flower" aria-hidden="true">❀</span><h1>这一轮，写完啦。</h1><p>不急着记住所有词，先看清这次的差别。</p><div class="summary-stats"><div><strong>'+clean+'</strong><span>独立写对</span></div><div><strong>'+hinted+'</strong><span>借助提示写对</span></div><div><strong>'+missed+'</strong><span>需要再练</span></div></div><div class="summary-actions">'+(needs.length?btn('重练没记牢的 '+needs.length+' 词','retry-round',''):btn('再来一组','quick-start',''))+btn('回到今日小本','go-home','secondary')+'</div><div class="round-results">'+results.map(function(r){var w=db.words.get(r.id);return '<div class="round-result"><div><strong>'+esc(w.word)+'</strong><p>'+esc(w.meaning)+'</p>'+(!r.correct?'<p>这次写成：'+esc(r.typed.trim()||'（暂时想不起）')+'</p>':'')+'</div><span class="result-label '+(r.independentCorrect?'':r.correct?'hinted':'retry')+'">'+(r.independentCorrect?'独立写对':r.correct?'用过提示':'再记一次')+'</span></div>';}).join('')+'</div></section>';}
  function empty(title,description,actions){return '<section class="empty"><div class="empty-icon" aria-hidden="true">♧</div><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p>'+(actions||'')+'</section>';}
  function filteredWords(){var query=filter.query.trim().toLowerCase();return data.words.filter(function(w){var r=state.records[w.id];if(route==='mistakes'&&!(r&&r.wrong>0))return false;if(filter.category!=='all'&&!w.tags.includes(filter.category))return false;if(query&&![w.word,w.meaning,w.pos].join(' ').toLowerCase().includes(query))return false;switch(filter.status){case 'active':return r&&r.wrong>0&&!C.isMastered(r);case 'mastered':return C.isMastered(r);case 'attempted':return r&&r.attempts>0;case 'unseen':return !r||!r.attempts;case 'due':return r&&r.attempts>0&&r.nextDue<=Date.now();case 'favorites':return r&&r.favorite;default:return true;}});}
  function library(){var mistake=route==='mistakes';return '<header class="page-title"><div><h1>'+ (mistake?'把错词，再写一遍。':'我的单词小本')+'</h1><p>'+(mistake?'错误记录会保留；连续3次独立写对后，移出待巩固列表。':'共 '+db.total+' 词，词性与词族分类可交叉。')+'</p></div>'+btn(mistake?'开始错词重练':'默写筛选结果','practice-filter','secondary small')+'</header><div class="library-controls"><label class="search-box"><span aria-hidden="true">⌕</span><input id="word-search" type="search" placeholder="搜单词或中文意思" aria-label="搜索单词" value="'+esc(filter.query)+'"></label><select id="word-category" class="select" aria-label="筛选单词分类">'+data.categories.map(function(c){return '<option value="'+c.id+'"'+(filter.category===c.id?' selected':'')+'>'+esc(c.title)+' · '+c.count+'</option>';}).join('')+'</select></div><div class="filter-chips">'+(mistake?[['active','还需巩固'],['all','全部曾错词'],['mastered','已连续写对']]:[['all','全部单词'],['unseen','还没练过'],['attempted','练习过'],['mastered','连续3次写对'],['due','到期复习'],['favorites','我的收藏']]).map(function(x){return '<button class="chip '+(filter.status===x[0]?'active':'')+'" data-act="filter-status" data-status="'+x[0]+'">'+x[1]+'</button>';}).join('')+'</div><div id="word-results">'+libraryResults()+'</div>';}
  function libraryResults(){var list=filteredWords(),size=20,total=Math.max(1,Math.ceil(list.length/size));page=Math.max(1,Math.min(page,total));if(!list.length)return empty(route==='mistakes'?'这里暂时没有要重练的错词':'没有找到对应单词',route==='mistakes'?'可以回到今日默写练一组，也可以切换“全部曾错词”回看历史。':'换个中文意思，或把筛选条件放宽一点。',btn('开始一组默写','quick-start',''));return '<div class="library-info"><span>'+list.length+' 个词'+(filter.status==='due'?'现在可以复习':'')+'</span><span>第 '+page+' / '+total+' 页</span></div><section class="word-list">'+list.slice((page-1)*size,page*size).map(function(w){var r=state.records[w.id],status=C.isMastered(r)?'连续3次写对':r?.attempts?(r.lastCorrect?'已练习':'上次写错'):'还没练过';return '<article class="word-row"><div class="word-main"><div class="word-title"><button data-act="word-detail" data-id="'+esc(w.id)+'">'+esc(w.word)+'</button><span class="phonetic">'+phonetic(w)+'</span></div><p>'+esc(w.meaning)+'</p></div><span class="word-state">'+status+'</span><button class="star-btn '+(r?.favorite?'saved':'')+'" data-act="favorite" data-id="'+esc(w.id)+'" aria-label="'+(r?.favorite?'取消收藏':'收藏')+esc(w.word)+'">'+(r?.favorite?'★':'☆')+'</button></article>';}).join('')+'</section><div class="pagination">'+btn('上一页','page-prev','secondary small',page<=1?'disabled':'')+'<span>'+page+' / '+total+'</span>'+btn('下一页','page-next','secondary small',page>=total?'disabled':'')+'</div>';}
  function mine(){var sum=C.summary(state),done=daily();return '<header class="page-title"><div><h1>我的小花园</h1><p>偏好、学习记录和备份，都在这里。</p></div></header><div class="settings-grid"><section class="panel"><h2>按自己的节奏练</h2><label class="setting-row"><span>每日小目标<small>包含新词和复习，不强制打卡</small></span><select id="setting-goal">'+[10,20,30,50].map(function(n){return '<option value="'+n+'"'+(settings.goal===n?' selected':'')+'>'+n+' 次默写</option>';}).join('')+'</select></label><label class="setting-row"><span>设备朗读口音</span><select id="setting-accent"><option value="en-US"'+(settings.accent==='en-US'?' selected':'')+'>美式英语</option><option value="en-GB"'+(settings.accent==='en-GB'?' selected':'')+'>英式英语</option></select></label><label class="setting-row"><span>朗读速度</span><select id="setting-rate">'+[[.65,'慢一点'],[.85,'清楚一点'],[1,'正常语速']].map(function(x){return '<option value="'+x[0]+'"'+(settings.rate===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('')+'</select></label><label class="setting-row"><span>听音模式自动读下一词</span><input id="setting-autoAudio" type="checkbox" '+(settings.autoAudio?'checked':'')+'></label>'+btn('试听一个单词','voice-test','secondary small')+'<p class="data-note">使用设备的英语语音。可用声音、口音和离线朗读取决于浏览器及已安装语音。</p></section><section class="panel"><h2>带走你的学习记录</h2><p>本机保存当前练习、输入草稿、提示记录、错词、收藏和复习时间。换设备时，导出后在新设备恢复。</p><div>'+btn('导出完整备份','backup','')+' '+btn('恢复备份','restore-open','secondary')+'</div><p class="data-note">iPhone、iPad和电脑不会自动同步。请保留备份，清理网站数据会移除本机记录。</p><p id="offline-label" class="offline-label" role="status">'+esc(offlineStatus)+'</p><p class="data-note">Safari 的分享菜单中可选择“添加到主屏幕”。首次联网完成离线保存后，可断网默写与核对。</p></section><section class="panel wide"><h2>一点点累积，也看得见</h2><div class="setting-totals"><span><strong>'+sum.attempted+'</strong>词练过</span><span><strong>'+sum.mastered+'</strong>词连续3次独立写对</span><span><strong>'+sum.wrong+'</strong>词曾经写错</span><span><strong>'+sum.favorites+'</strong>词已收藏</span><span><strong>'+Math.round(sum.accuracy*100)+'%</strong>独立正确率</span></div><p>独立写对：本轮第一次检查正确，且没有使用提示。使用提示、看答案或之后改对，不会抹去首次错误。复习按作答安排，写错约5分钟后、提示后约30分钟后；独立写对后逐步延长。连续3次是练习记录标记，不代表长期记忆已经稳定。</p></section><section class="panel wide"><h2>这本词库从哪里来</h2><p>'+esc(data.meta.sourceNote)+'</p><p>'+esc(data.meta.meaningNote)+'</p><p class="data-note">'+esc(data.meta.orderNote)+' '+esc(data.meta.spellingNote)+'</p><p class="data-note">数据依据 CC BY-NC-SA 4.0 用于非商业学习；ECDICT 与 CMUdict 保留各自许可。分类可重叠，字形和读音候选用于查找线索。</p><div class="source-links"><a href="licenses/ATTRIBUTION.txt" target="_blank" rel="noopener">来源与署名</a><a href="licenses/NETEM.txt" target="_blank" rel="noopener">词表许可</a><a href="licenses/ECDICT.txt" target="_blank" rel="noopener">词典许可</a><a href="licenses/cmudict.txt" target="_blank" rel="noopener">读音数据许可</a></div></section></div>'+footer();}
  function render(focusInput){if(!loaded)return;if(loadError){main.innerHTML=empty('先保留这本小本',loadError,btn('导出原始记录','raw-backup','secondary')+' '+btn('恢复有效备份','restore-open',''));return;}if(route==='summary'&&session?.completedAt===null)route='practice';main.innerHTML='<div id="save-status" class="storage-error" role="alert" hidden></div>'+({home:home,practice:practice,summary:roundSummary,words:library,mistakes:library,mine:mine}[route]||home)();storageBanner();document.querySelectorAll('[data-nav]').forEach(function(a){var current=route==='practice'||route==='summary'?'home':route;a.classList.toggle('active',a.dataset.nav===current);if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=(route==='practice'?'默写中 · ':route==='mistakes'?'错词重练 · ':'')+'词芽 · 考研单词默写';if(focusInput&&route==='practice'&&!session?.results[C.currentId(session)])document.getElementById('spelling-input')?.focus({preventScroll:true});}
  function openDialog(title,body){dialog.innerHTML='<div class="dialog-title-row"><h2 id="dialog-title">'+esc(title)+'</h2><button class="dialog-close" data-act="close-dialog" aria-label="关闭窗口">×</button></div>'+body;dialog.showModal();}
  function closeDialog(){if(dialog.open)dialog.close();startChoice=null;}
  function setup(category,ids){var audioOK='speechSynthesis'in window;startChoice={category:category||'all',ids:ids||null};openDialog('今天，想怎么写？','<form id="setup-form"><label class="field"><span>默写方式</span><select name="mode"><option value="meaning">看中文，拼英文</option><option value="audio"'+(!audioOK?' disabled':'')+'>听读音，写单词'+(!audioOK?'（本浏览器暂不支持）':'')+'</option></select></label><label class="field"><span>这一组练哪些词</span><select name="category" '+(ids?'disabled':'')+'>'+[['all','全部核心词'],['due','到期复习'],['wrong','全部曾错词'],['favorites','我的收藏']].concat(data.categories.filter(function(c){return c.id!=='all';}).map(function(c){return[c.id,c.title];})).map(function(x){return '<option value="'+x[0]+'"'+(x[0]===(category||'all')?' selected':'')+'>'+esc(x[1])+'</option>';}).join('')+'</select></label><label class="field"><span>每组词数'+(ids?' · 本次筛选有 '+ids.length+' 词':'')+'</span><select name="count">'+[10,20,30,50].map(function(n){return '<option value="'+n+'"'+(n===settings.goal?' selected':'')+'>'+n+' 词</option>';}).join('')+'</select></label><label class="field"><span>练习顺序</span><select name="order"><option value="smart">先复习到期词，再练新词</option><option value="random">在这一组随机抽词</option></select></label><p class="dialog-text">分类数量不够时，按实际词数练习。'+(session&&session.completedAt===null?'开始新一轮会结束当前轮，已记录的学习结果保留。':'进度会自动保存，可以随时回来继续。')+'</p><div class="dialog-actions"><button type="submit" class="btn">开始这一组 →</button>'+btn('再想一下','close-dialog','secondary')+'</div></form>');}
  function start(options){if(options.mode==='audio'&&!('speechSynthesis'in window)){toast('本浏览器暂不支持设备朗读，请先使用看中文默写。');return;}var next=C.createSession(db,state,options);if(!next.ids.length){toast(options.category==='due'?'现在还没有到期复习词，可以先练新词。':'这一组暂时没有可练习的单词。');return;}session=next;hintView='';persist();closeDialog();if(location.hash==='#practice'){route='practice';render(true);window.scrollTo(0,0);}else{location.hash='practice';setTimeout(function(){document.getElementById('spelling-input')?.focus({preventScroll:true});},50);}if(session.mode==='audio'&&settings.autoAudio)speak(db.words.get(session.ids[0]),false);}
  function quickStart(){if(session&&session.completedAt===null){setup('all');return;}start({category:'all',mode:'meaning',count:settings.goal,order:'smart'});}
  function check(skip){if(!session||session.completedAt!==null)return;var id=C.currentId(session),word=db.words.get(id);if(session.results[id])return;var input=document.getElementById('spelling-input'),typed=skip?'':input.value;if(!skip&&!typed.trim()){toast('先写一个单词，或选择“暂时想不起”。');input.focus();return;}C.submit(state,session,word,typed);persist();render();document.querySelector('[data-act="next"]')?.focus({preventScroll:true});}
  function advance(){if(!session||session.completedAt!==null)return;C.next(session);hintView='';persist();if(session.completedAt!==null){navigate('summary');return;}render(true);window.scrollTo({top:0,behavior:'instant'});if(session.mode==='audio'&&settings.autoAudio)speak(db.words.get(C.currentId(session)),false);}
  function useHint(kind){if(!session||session.completedAt!==null||session.results[C.currentId(session)])return;C.useHint(session);hintView=kind;persist();var value=document.getElementById('spelling-input')?.value||session.draft;render(true);var input=document.getElementById('spelling-input');if(input)input.value=value;}
  function speak(word,countsHint){if(!word)return;if(!('speechSynthesis'in window)){toast('本浏览器暂不支持朗读，可以用中文默写。');return;}if(countsHint&&session&&!session.results[C.currentId(session)]){C.useHint(session);persist();var note=document.querySelector('.round-note');if(note)note.lastElementChild.textContent='这题用过提示，会安排再复习。';}speechSynthesis.cancel();audio=new SpeechSynthesisUtterance(word.word);audio.lang=settings.accent;audio.rate=settings.rate;var voices=speechSynthesis.getVoices(),voice=voices.find(function(v){return v.lang.toLowerCase()===settings.accent.toLowerCase();})||voices.find(function(v){return /^en[-_]/i.test(v.lang);});if(voice)audio.voice=voice;audio.onerror=function(e){if(!['interrupted','canceled'].includes(e.error))toast('设备朗读暂未成功，请检查声音或改用看中文默写。');};speechSynthesis.speak(audio);}
  function download(name,value){var url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(function(){URL.revokeObjectURL(url);},10000);}
  function detail(id){var word=db.words.get(id);if(!word)return;var related=(word.comparisonGroups||[]).map(function(g){return data.groups.find(function(v){return v.id===g;});}).filter(Boolean),siblings=[...new Set(related.flatMap(function(g){return g.words;}))].filter(function(w){return w!==id&&db.words.has(w);}).slice(0,10);openDialog('看看这个词','<div class="word-detail-body"><div class="word-detail-title">'+esc(word.word)+' <button class="audio-btn" data-act="speak-word" data-id="'+esc(word.id)+'" aria-label="朗读'+esc(word.word)+'">♪</button></div><p class="muted">'+phonetic(word)+' · '+esc(word.pos)+'</p><p>'+esc(word.meaning)+'</p>'+(word.example?'<div class="example-note"><p>'+highlightWord(word.example.sentence,word.word)+'</p><p class="muted">'+esc(word.example.zh)+'</p></div>':'')+(word.examNote?'<p class="dialog-text">'+esc(word.examNote)+'</p>':'')+(siblings.length?'<h3>同组词，放在一起看清</h3>'+siblings.map(function(id){var w=db.words.get(id);return '<div class="word-compare"><strong>'+esc(w.word)+'</strong><p>'+esc(w.meaning)+'</p></div>';}).join(''):'')+'<div class="dialog-actions">'+btn('单独默写这个词','one-word','','data-id="'+esc(word.id)+'"')+btn(state.records[id]?.favorite?'取消收藏':'收藏这个词','favorite','secondary','data-id="'+esc(word.id)+'"')+'</div></div>');}
  document.addEventListener('click',function(event){var el=event.target.closest('[data-act]');if(!el||el.disabled||!loaded)return;var action=el.dataset.act,id=el.dataset.id;try{
    if(action==='quick-start')quickStart();
    else if(action==='setup')setup('all');
    else if(action==='resume')navigate(session?.completedAt===null?'practice':'summary');
    else if(action==='category')setup(el.dataset.category);
    else if(action==='next')advance();
    else if(action==='skip')check(true);
    else if(action==='hint-first')useHint('first');
    else if(action==='hint-phonetic')useHint('phonetic');
    else if(action==='hint-meaning')useHint('meaning');
    else if(action==='listen'){var w=db.words.get(C.currentId(session));speak(w,session.mode!=='audio'&&!session.results[w.id]);}
    else if(action==='favorite'){C.toggleFavorite(state,id);persist();el.classList.toggle('saved',!!state.records[id].favorite);if(el.classList.contains('star-btn')){el.textContent=state.records[id].favorite?'★':'☆';el.setAttribute('aria-label',(state.records[id].favorite?'取消收藏':'收藏')+id);}else el.textContent=state.records[id].favorite?'取消收藏':'收藏这个词';if(['words','mistakes'].includes(route)&&filter.status==='favorites')document.getElementById('word-results').innerHTML=libraryResults();}
    else if(action==='word-detail')detail(id);
    else if(action==='speak-word')speak(db.words.get(id),false);
    else if(action==='one-word'){if(session&&session.completedAt===null)setup('all',[id]);else start({mode:'meaning',category:'all',count:10,order:'smart',ids:[id]});}
    else if(action==='library-filter')navigate('words?status='+el.dataset.status);
    else if(action==='filter-status'){filter.status=el.dataset.status;page=1;render();}
    else if(action==='practice-filter'){var ids=filteredWords().map(function(w){return w.id;});if(ids.length)setup('all',ids);else toast('这次筛选里还没有单词。');}
    else if(action==='retry-round'){var ids=session.ids.filter(function(id){return !session.results[id]?.independentCorrect;});start({mode:session.mode,category:'all',count:ids.length<=10?10:ids.length<=20?20:ids.length<=30?30:50,order:'smart',ids:ids});}
    else if(action==='go-home')navigate('home');
    else if(action==='page-prev'||action==='page-next'){page+=action==='page-next'?1:-1;document.getElementById('word-results').innerHTML=libraryResults();document.querySelector('.library-controls').scrollIntoView({block:'start'});}
    else if(action==='backup')download('词芽-默写完整备份-'+new Date().toISOString().slice(0,10)+'.json',envelope(state,session,settings));
    else if(action==='raw-backup')download('词芽-原始记录.json',rawStored||'{}');
    else if(action==='restore-open')document.getElementById('backup-file').click();
    else if(action==='restore-confirm'){if(!staged)return;var next=envelope(staged.state,staged.session,staged.settings);localStorage.setItem(STORE,JSON.stringify(next));state=staged.state;session=staged.session;settings=staged.settings;hintView='';staged=null;loadError='';storageError='';closeDialog();navigate('home');render();toast('小本已恢复，可以继续默写。');}
    else if(action==='close-dialog')closeDialog();
    else if(action==='voice-test')speak(db.words.get('generally')||data.words[0],false);
  }catch(err){showError(err.message||'操作没有完成，请再试一次。');}});
  function showError(message){if(dialog.open){var p=dialog.querySelector('.dialog-error');if(!p){p=document.createElement('p');p.className='dialog-error';p.setAttribute('role','alert');dialog.append(p);}p.textContent=message;}else toast(message);}
  document.addEventListener('submit',function(event){if(event.target.id==='answer-form'){event.preventDefault();try{check(false);}catch(err){showError(err.message);}}else if(event.target.id==='setup-form'){event.preventDefault();try{var d=new FormData(event.target),choice=startChoice||{};start({mode:d.get('mode'),category:choice.ids?'all':d.get('category'),count:Number(d.get('count')),order:d.get('order'),...(choice.ids?{ids:choice.ids}:{})});}catch(err){showError(err.message);}}});
  document.addEventListener('input',function(event){if(event.target.id==='spelling-input'&&session&&!session.results[C.currentId(session)]){session.draft=event.target.value;persist();}else if(event.target.id==='word-search'){filter.query=event.target.value;page=1;document.getElementById('word-results').innerHTML=libraryResults();}});
  document.addEventListener('change',function(event){var el=event.target;if(el.id==='word-category'){filter.category=el.value;page=1;document.getElementById('word-results').innerHTML=libraryResults();}else if(el.id.startsWith('setting-')){var key=el.id.slice(8);settings[key]=el.type==='checkbox'?el.checked:key==='goal'||key==='rate'?Number(el.value):el.value;persist();toast('偏好已保存。');}});
  document.addEventListener('keydown',function(event){if(event.key!=='Enter'||event.isComposing||event.repeat||dialog.open||route!=='practice')return;var el=event.target;if(el.id==='spelling-input')return;if(session?.results[C.currentId(session)]&&['BODY','MAIN'].includes(el.tagName)){event.preventDefault();advance();}});
  document.getElementById('backup-file').addEventListener('change',async function(event){var file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('请选择8MB以内的词芽备份。');staged=validateEnvelope(JSON.parse(await file.text()));openDialog('把这份小本恢复回来？','<p class="dialog-text">这份备份包含 '+Object.keys(staged.state.records).filter(function(id){return staged.state.records[id].attempts;}).length+' 个已练词，'+(staged.session&&staged.session.completedAt===null?'还有一轮未完成练习。':'可以接着安排下一轮。')+'</p><p class="dialog-text">恢复会替换当前词芽记录。建议先导出当前备份；研习和词辨的记录不受影响。</p><div class="dialog-actions">'+btn('确认恢复','restore-confirm','')+btn('取消','close-dialog','secondary')+'</div>');}catch(err){staged=null;toast('没有修改现有记录：'+(err.message||'备份无法读取。'));}});
  window.addEventListener('hashchange',readRoute);window.addEventListener('pagehide',function(){if(loaded&&!loadError)persist();if('speechSynthesis'in window)speechSynthesis.cancel();});
  window.addEventListener('storage',function(event){if(event.key!==STORE||!loaded)return;try{if(event.newValue){var clean=validateEnvelope(JSON.parse(event.newValue));state=clean.state;session=clean.session;settings=clean.settings;hintView='';render();toast('另一个窗口更新了这本小本。');}}catch(_){toast('另一个窗口的记录无法读取，请保留当前备份。');}});
  async function installOffline(){if(!('serviceWorker'in navigator)||!isSecureContext){offlineStatus='当前浏览器不支持离线保存，联网仍可使用。';return;}try{var registration=await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;var worker=registration.installing||registration.waiting||registration.active;if(worker&&worker.state!=='activated')await new Promise(function(resolve){worker.addEventListener('statechange',function(){if(worker.state==='activated')resolve();});setTimeout(resolve,20000);});worker=registration.active;if(!worker)throw Error('未就绪');var status=await new Promise(function(resolve,reject){var ch=new MessageChannel(),t=setTimeout(function(){reject(Error('检查超时'));},12000);ch.port1.onmessage=function(event){clearTimeout(t);resolve(event.data);};worker.postMessage({type:'CIYA_OFFLINE_STATUS'},[ch.port2]);});offlineStatus=status.ready?'小本已离线保存，可以断网默写。':'离线保存还没有完成，请保持联网后重新打开。';}catch(_){offlineStatus='离线保存暂未完成，联网使用与当前学习记录不受影响。';}var label=document.getElementById('offline-label');if(label)label.textContent=offlineStatus;}
  async function load(){try{var response=await fetch('data.json');if(!response.ok)throw Error('词库暂时无法载入。');data=await response.json();db=C.index(data);if(db.total<3600)throw Error('词库未完整载入。');saveLoad();loaded=true;document.getElementById('header-note').textContent='考研核心精选 · '+db.total.toLocaleString()+' 词';readRoute();installOffline();}catch(err){main.innerHTML=empty('小本还没有打开',err.message||'请检查网络后重试。','<button class="btn" onclick="location.reload()">重新打开</button>');}}
  load();
})();
